 const MAX_CONTENT_LENGTH = 10000;

@@ -25,16 +25,66 @@ export function validateMessage(payload: unknown): ValidationResult {
     return {valid: false, error: 'Message must have a type field'};
   }

+  // eslint-disable-next-line re-lint/prefer-polymorphism -- discriminated-union narrowing on an untrusted frame (adrs/ADR-006-lint-suppressions.md)
   switch (message.type) {
     case 'user_message':
       return validateUserMessage(message);
     case 'ping':
       return validatePingMessage(message);
+    case 'list_sessions':
+      return validateListSessionsMessage(message);
     default:
       return {valid: false, error: `Unknown message type: ${message.type}`};
   }
 }

+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const result: ListSessionsMessage = {
+    type: 'list_sessions',
+  };
+
+  if ('limit' in message && message.limit !== undefined) {
+    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
+      return {valid: false, error: 'limit must be a non-negative integer'};
+    }
+    result.limit = message.limit;
+  }
+
+  if ('before' in message && message.before !== undefined) {
+    if (typeof message.before !== 'object' || message.before === null || Array.isArray(message.before)) {
+      return {valid: false, error: 'before must be an object'};
+    }
+    const before = message.before as Record<string, unknown>;
+
+    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
+      return {valid: false, error: 'before.sessionId must be between 1 and 128 characters'};
+    }
+
+    if (typeof before.updatedAt !== 'string' && typeof before.updatedAt !== 'number') {
+      return {valid: false, error: 'before.updatedAt must be a date string or timestamp'};
+    }
+
+    if (typeof before.updatedAt === 'string') {
+      const parsed = Date.parse(before.updatedAt);
+      if (Number.isNaN(parsed)) {
+        return {valid: false, error: 'before.updatedAt must parse as a valid timestamp'};
+      }
+    } else if (!Number.isFinite(before.updatedAt)) {
+      return {valid: false, error: 'before.updatedAt must be a finite timestamp'};
+    }
+
+    result.before = {
+      sessionId: before.sessionId,
+      updatedAt: before.updatedAt,
+    };
+  }
+
+  return {
+    valid: true,
+    data: result,
+  };
+}
